#include <bits/stdc++.h>
using namespace std;

int main() {
    double profit;
    cin >> profit;

    const double cap[6] = {100000, 200000, 400000, 600000, 1000000, 1e18};
    const double rate[6] = {0.10, 0.075, 0.05, 0.03, 0.015, 0.01};

    double total = 0, prev = 0;
    for (int i = 0; i < 6; i++) {
        if (profit > prev) total += (min(profit, cap[i]) - prev) * rate[i];
        prev = cap[i];
        if (profit <= cap[i]) break;
    }

    cout << fixed << setprecision(2) << total << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// 最多 5 种商品，每种最多 5 件：把编号离散化到 0..4
int need[5], price[5], have;
int s;
vector<pair<vector<pair<int, int>>, int>> plans;  // ((商品槽位, 数量), ...), 价格

// memo[base5 编码] = 最小费用；-1 表示未计算
int memo[7776];

int solve(int state) {
    int &res = memo[state];
    if (res != -1) return res;

    // 还原每种商品的剩余需求
    int rem[5], t = state;
    bool done = true;
    for (int i = 0; i < have; i++) {
        rem[i] = t % 6; t /= 6;
        if (rem[i]) done = false;
    }
    if (done) return res = 0;

    // 方案一：剩下的全部按原价买
    res = 0;
    for (int i = 0; i < have; i++) res += rem[i] * price[i];

    // 方案二：挑一个促销方案买掉，再递归补齐
    for (auto &pl : plans) {
        int ns = state, cost = pl.second;
        bool ok = true;
        for (auto &item : pl.first) {
            int slot = item.first, qty = item.second;
            int cur = (state / (int)pow(6, slot)) % 6;
            if (cur < qty) { ok = false; break; }
            ns -= qty * (int)pow(6, slot);
        }
        if (!ok) continue;              // 超出需求，就是买多了，不允许
        res = min(res, cost + solve(ns));
    }
    return res;
}

int main() {
    cin >> s;
    for (int i = 0; i < s; i++) {
        int n, p;
        cin >> n >> p;
        vector<pair<int, int>> items;
        for (int j = 0; j < n; j++) {
            int c, k;
            cin >> c >> k;
            items.push_back({c, k});
        }
        plans.push_back({items, p});
    }

    int b;
    cin >> b;
    int mapCode[1000];
    fill(mapCode, mapCode + 1000, -1);
    have = 0;
    for (int i = 0; i < b; i++) {
        int c, k, p;
        cin >> c >> k >> p;
        if (mapCode[c] == -1) mapCode[c] = have++;
        need[mapCode[c]] = k;
        price[mapCode[c]] = p;
    }
    // 把方案里的商品编号也映射到槽位；方案中提到清单外的商品则该方案不可用
    for (auto &pl : plans) {
        vector<pair<int, int>> keep;
        for (auto &it : pl.first) {
            if (mapCode[it.first] == -1) { keep.clear(); break; }
            keep.push_back({mapCode[it.first], it.second});
        }
        pl.first = keep;
    }

    int start = 0;
    for (int i = 0; i < have; i++) start += need[i] * (int)pow(6, i);

    fill(memo, memo + 7776, -1);
    cout << solve(start) << endl;
    return 0;
}
